int parse_layout(const char *path, layout_def *layout) {
    FILE *fp;
    char line[256];

    if (!path || !layout)
        return -1;
    fp = fopen(path, "r");
    if (!fp)
        return -1;
    memset(layout, 0, sizeof(*layout));
    while (fgets(line, sizeof(line), fp)) {
        char name[64], kind[16];
        unsigned off, size;
        if (sscanf(line, "STRUCT %63s", layout->struct_name) == 1)
            continue;
        if (sscanf(line, "FIELD %63s %15s %u %u", name, kind, &off, &size) == 4) {
            field_def *f;
            if (layout->nfields >= FIELD_MAX ||
                (strcmp(kind, "u32") != 0 && strcmp(kind, "u64") != 0) ||
                (strcmp(kind, "u32") == 0 && size != 4) ||
                (strcmp(kind, "u64") == 0 && size != 8)) {
                fclose(fp);
                return -1;
            }
            f = &layout->fields[layout->nfields++];
            snprintf(f->name, sizeof(f->name), "%s", name);
            snprintf(f->kind, sizeof(f->kind), "%s", kind);
            f->off = off;
            f->size = size;
        }
    }
    fclose(fp);
    return layout->struct_name[0] && layout->nfields > 0 ? 0 : -1;
}
