        return 1;
    }
    fp = fopen(inspect_path, "rb");
    if (!fp) {
        perror("probe");
        return 1;
    }
    nread = fread(blob, 1, sizeof(blob), fp);
    fclose(fp);
    for (int i = 0; i < layout.nfields; i++) {
        const field_def *f = &layout.fields[i];
        if (f->off > nread || f->size > nread - f->off) {
            fprintf(stderr, "probe: inspect too short for %s\n", f->name);
            return 1;
        }
